func TestAnEmptySessionRendersTheTableNotAMessage(t *testing.T) {
	m := newModel(t)
	if body := m.Render(); body != m.runTable.View() {
		t.Errorf("an empty session's body is %q, want the plain table view", body)
	}
	if _, _, ok := findHeaderInfo(m, "Runs"); !ok {
		t.Fatal("GetHeaderInfo has no Runs count")
	}
	if _, value, _ := findHeaderInfo(m, "Runs"); value != "0" {
		t.Errorf("GetHeaderInfo Runs = %q, want \"0\"", value)
	}

	m2 := withRuns(t, run(1, jobs.KindScan, "~/work", jobs.ItemDone))
	m2, _ = step(t, m2, testutil.Key("/"))
	for _, msg := range testutil.Type("nothing-matches-this") {
		m2, _ = step(t, m2, msg)
	}
	if body := m2.Render(); body != m2.runTable.View() {
		t.Errorf("a filter hiding every row renders %q, want the plain table view", body)
	}
	if _, value, _ := findHeaderInfo(m2, "Runs"); value != "1" {
		t.Errorf("GetHeaderInfo Runs = %q, want the unfiltered total \"1\"", value)
	}
}

func findHeaderInfo(m Model, key string) (foundKey, value string, ok bool) {
	for _, info := range m.GetHeaderInfo(testContext) {
		if info.Key == key {
			return info.Key, info.Value, true
		}
	}
	return "", "", false
}

func TestTheFooterCountsWhatIsRunning(t *testing.T) {
	m := withRuns(t,
		run(1, jobs.KindScan, "~/work", jobs.ItemRunning),
		run(2, jobs.KindSync, "~/perso", jobs.ItemQueued),
		run(3, jobs.KindScan, "~/old", jobs.ItemDone),
	)

	status := m.status()
	if want := "2 jobs running"; status.Text != want {
		t.Errorf("the footer says %q, want %q", status.Text, want)
	}
	// A selected row brings its own sentence and a dot that moves, so the
	// footer spinner is dropped (DEVDESK-142).
	if status.Spinner || status.Detail.IsZero() {
		t.Errorf("Spinner = %v, Detail zero = %v; want no spinner beside a detail", status.Spinner, status.Detail.IsZero())
	}
	// The sentence stops there: ":jobs for details" is what every other footer
	// adds, and this is where that link leads.
	if strings.Contains(status.Text, ":jobs") {
		t.Error("the jobs view points at itself")
	}
}

func TestTheFooterIsSilentWhenNothingRuns(t *testing.T) {
	m := withRuns(t, run(1, jobs.KindScan, "~/work", jobs.ItemDone))
	if got := m.status().Text; got != "" {
		t.Errorf("the footer says %q with nothing running", got)
	}
}

